<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_admin();require __DIR__.'/../../app/helpers/layout.php';if(is_post()){csrf_check();$id=(int)$_POST['id'];$status=in_array($_POST['status'],['publik','privat','ditolak','menunggu'],true)?$_POST['status']:'menunggu';$pdo->prepare('UPDATE repositories SET status=? WHERE id=?')->execute([$status,$id]);log_activity($pdo,$u['id'],'admin','Ubah status repository','Repository #'.$id.' -> '.$status);flash('success','Status repository diperbarui.');redirect('/admin/repository/review.php');}render_start('Review Repository','Verifikasi karya ilmiah',$u);dashboard_nav('admin');render_mid('Review Repository','Ubah status publikasi',$u);$rows=$pdo->query('SELECT * FROM repositories ORDER BY id DESC')->fetchAll();?><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Judul</th><th>Penulis</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['author'])?></td><td><?=e($r['status'])?></td><td><form method="post" style="display:flex;gap:6px"><?=csrf_input()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option value="menunggu">Menunggu</option><option value="publik">Publik</option><option value="privat">Privat</option><option value="ditolak">Ditolak</option></select><button class="btn btn-primary">Simpan</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php render_end(); ?>
